var import_obsidian3 = require("obsidian");
var NoteSuggest = class extends import_obsidian3.AbstractInputSuggest {
  constructor(app, textarea, onChoose) {
    super(app, textarea);
    /** 当前查询（renderSuggestion 高亮命中片段用） */
    this.currentQuery = "";
    this.textarea = textarea;
    this.onChoose = onChoose;
    this.limit = 20;
  }
  getValue() {
    return this.textarea.value;
  }
  setValue(value) {
    this.textarea.value = value;
  }
  /** @ 触发：光标前有 @token 且能匹配到笔记才弹列表，否则关闭 */
  onInputChange() {
    const hit = atToken(this.textarea.value, this.textarea.selectionStart ?? this.textarea.value.length);
    if (!hit) {
      this.close();
      return;
    }
    const items = this.getSuggestions(hit.token);
    if (items.length > 0) {
      this.showSuggestions(items);
    } else {
      this.close();
    }
  }
  getSuggestions(query) {
    const q = query.toLowerCase();
    this.currentQuery = q;
    return this.app.vault.getMarkdownFiles().filter((f) => !q || f.basename.toLowerCase().includes(q) || f.path.toLowerCase().includes(q)).sort((a, b) => {
      const ab2 = a.basename.toLowerCase().includes(q) ? 0 : 1;
      const bb2 = b.basename.toLowerCase().includes(q) ? 0 : 1;
      if (ab2 !== bb2) return ab2 - bb2;
      return a.basename.localeCompare(b.basename, "zh");
    });
  }
  renderSuggestion(file, el2) {
    el2.empty();
    const title = el2.createDiv({ cls: "suggestion-title" });
    const q = this.currentQuery;
    const idx = q ? file.basename.toLowerCase().indexOf(q) : -1;
    if (idx >= 0) {
      title.appendText(file.basename.slice(0, idx));
      title.createEl("mark", { text: file.basename.slice(idx, idx + q.length) });
      title.appendText(file.basename.slice(idx + q.length));
    } else {
      title.setText(file.basename);
    }
    const folder = file.parent && file.parent.path !== "/" ? file.parent.path : "";
    if (folder) el2.createDiv({ cls: "suggestion-note", text: folder });
  }
  selectSuggestion(file, evt) {
    const cursor = this.textarea.selectionStart ?? this.textarea.value.length;
    const hit = atToken(this.textarea.value, cursor);
    if (hit) {
      this.textarea.setRangeText(`[[${file.basename}]]`, hit.start, cursor, "end");
      this.textarea.focus();
    }
    this.onChoose(file);
    this.close();
  }
  /** 建议框是否打开（keydown 守卫用；isOpen 未在类型中暴露） */
  isSuggestOpen() {
    return !!this.isOpen;
  }
};

// src/viewlogic.ts
function citeRefRe() {
  return /【📖\s*([^】]+?):(\d+)(?:-(\d+))?】/g;
}
function paragraphReady(t) {
  let fences = 0;
  for (const line of t.split("\n")) {
    if (line.trimStart().startsWith("```")) fences++;
  }
  if (fences % 2 !== 0) return false;
  return t.split("\\(").length - 1 === t.split("\\)").length - 1 && t.split("\\[").length - 1 === t.split("\\]").length - 1;
}
function splitCommittableParagraphs(pending) {
  const parts = pending.split("\n\n");
  const done = [];
  let rest = "";
  for (let i = 0; i < parts.length; i++) {
    if (i < parts.length - 1 && paragraphReady(parts[i])) {
      done.push(parts[i]);
    } else {
      rest = parts.slice(i).join("\n\n");
      break;
    }
  }
  return { done, rest };
}
function attachCitationButtonsDOM(container, onNavigate) {
  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) {
    const text = node.nodeValue ?? "";
    if (!text.includes("\u3010\u{1F4D6}")) continue;
    const re2 = citeRefRe();
    const frag = document.createDocumentFragment();
    let last = 0;
    let replaced = 0;
    let m;
    while ((m = re2.exec(text)) !== null) {
      frag.appendChild(document.createTextNode(text.slice(last, m.index)));
      const file = m[1].trim();
      const line = parseInt(m[2], 10);
      const btn = document.createElement("button");
      btn.className = "edge-tutor-cite-btn";
      btn.textContent = `\u{1F4D6} ${file}:${line}`;
      btn.addEventListener("click", () => onNavigate({ file, line }));
      frag.appendChild(btn);
      replaced++;
      last = m.index + m[0].length;
    }
    if (replaced > 0) {
      frag.appendChild(document.createTextNode(text.slice(last)));
      node.replaceWith(frag);
    }
  }
}
function attachCodeCopyButtonsDOM(container, notify, onError) {
  for (const pre of Array.from(container.querySelectorAll("pre"))) {
    if (pre.querySelector(".edge-tutor-code-copy")) continue;
    const code = pre.querySelector("code");
    if (!code) continue;
    pre.classList.add("edge-tutor-code-block");
    const btn = document.createElement("button");
    btn.className = "edge-tutor-code-copy";
    btn.textContent = "\u{1F4CB}";
    btn.setAttribute("title", "\u590D\u5236\u4EE3\u7801");
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      try {
        await navigator.clipboard.writeText(code.textContent ?? "");
        notify("\u5DF2\u590D\u5236\u4EE3\u7801");
      } catch (err) {
        onError?.(err);
        notify("\u590D\u5236\u5931\u8D25\uFF0C\u8BF7\u624B\u52A8\u9009\u62E9\u590D\u5236");
      }
    });
    pre.appendChild(btn);
  }
}
function normalizeMath(text) {
  let out = text;
  out = out.replace(/\\\[[\s\S]*?\\\]/g, (m) => "$$" + m.slice(2, -2).trim() + "$$");
  out = out.replace(/\\\(([^\\]*?)\\\)/g, (m) => "$" + m.slice(2, -2).trim() + "$");
  out = out.replace(/\\\(/g, "$").replace(/\\\)/g, "$");
  out = out.replace(/\\\[/g, "$$").replace(/\\\]/g, "$$");
  return out;
}
function buildGuideEntryBox(entry, opts) {
  const box = document.createElement("div");
  box.className = "edge-tutor-entry";
  const heading = box.createEl("h5");
  heading.createSpan({
    text: entry.type === "deepen" ? "\u{1F53B} \u6DF1\u5316" : "\u{1F195} \u65B0\u57DF",
    cls: "edge-tutor-entry-badge" + (entry.type === "deepen" ? " deepen" : "")
  });
  heading.createSpan({ text: entry.id + " " + entry.title });
  if (entry.jiang) heading.createSpan({ text: " \xB7 " + entry.jiang, cls: "edge-tutor-entry-meta" });
  const rows = [];
  if (entry.type === "deepen" && entry.anchorNode) rows.push(["\u951A\u5B9A\u8282\u70B9", "[[" + entry.anchorNode + "]]"]);
  if (entry.question) rows.push(["\u4E0B\u4E00\u5835\u5899", entry.question]);
  if (entry.direction) rows.push(["\u5EF6\u4F38\u65B9\u5411", entry.direction]);
  if (entry.whyWorthExploring) rows.push(["\u4E3A\u4EC0\u4E48\u503C\u5F97\u8FFD", entry.whyWorthExploring]);
  if (entry.entryPoint) rows.push(["\u81EA\u7136\u5207\u5165\u53E3", entry.entryPoint]);
  if ((entry.tensions ?? []).length) rows.push(["\u5173\u952E\u5F20\u529B", (entry.tensions ?? []).join("\uFF1B")]);
  if ((entry.connections ?? []).length) rows.push(["\u53EF\u8FDE\u63A5", (entry.connections ?? []).join("\uFF1B")]);
  if ((entry.possibleTrails ?? []).length) rows.push(["\u53EF\u80FD\u5C3E\u8FF9", (entry.possibleTrails ?? []).join("\uFF1B")]);
  if (entry.anchor) rows.push(["\u6559\u6750\u951A\u70B9", entry.anchor]);
  for (const [k3, v] of rows) {
    const line = box.createEl("p", { cls: "edge-tutor-entry-row" });
    line.createEl("strong", { text: k3 + "\uFF1A" });
    line.createSpan({ text: v });
  }
  const start = box.createEl("button", { text: "\u4ECE\u8FD9\u91CC\u5F00\u59CB\u63A2\u7D22", cls: "edge-tutor-entry-start" });
  start.addEventListener("click", () => {
    if (opts.isBusy()) return;
    opts.onStart(entry);
  });
  return box;
}
function buildMsgActBar(host, buttons) {
  const acts = host.createEl("div", { cls: "edge-tutor-msg-acts" });
  for (const btn of buttons) {
    const b = acts.createEl("button", {
      text: btn.label,
      cls: "edge-tutor-msg-act" + (btn.danger ? " danger" : ""),
      attr: { title: btn.tip }
    });
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      void btn.handler();
    });
  }
}

// src/modals.ts
var import_obsidian4 = require("obsidian");
var PromptModal = class extends import_obsidian4.Modal {
  constructor(app, title, placeholder = "", initial = "") {
    super(app);
    this.placeholder = placeholder;
    this.initial = initial;
    this.titleEl.setText(title);
  }
  openPrompt() {
    return new Promise((resolve) => {
      this.resolve = resolve;
      this.open();
    });
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    const input = contentEl.createEl("input", {
      type: "text",
      attr: { placeholder: this.placeholder, value: this.initial }
    });
    input.addClass("edge-tutor-prompt-input");
    input.focus();
    input.select();
    const submit = () => {
      const v = input.value.trim();
      this.resolve(v || null);
      this.close();
    };
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") submit();
      if (e.key === "Escape") {
        this.resolve(null);
        this.close();
      }
    });
    const btnRow = contentEl.createEl("div", { cls: "edge-tutor-prompt-btns" });
    const okBtn = btnRow.createEl("button", { text: "\u786E\u5B9A", cls: "mod-cta" });
    okBtn.addEventListener("click", submit);
    const cancelBtn = btnRow.createEl("button", { text: "\u53D6\u6D88" });
    cancelBtn.addEventListener("click", () => {
      this.resolve(null);
      this.close();
    });
  }
  onClose() {
    const { contentEl } = this;
    contentEl.empty();
  }
};
