  /** ===== 锚点定位（Obsidian markdown 文本锚点，替代 Zotero PDF 框选） ===== */
  /**
   * 打开 markdown 文件并定位到引用文本。
   * Obsidian 适配：Zotero 是 PDF 页内框选定位，Obsidian 无此能力 →
   * 改为打开文件后搜索引用文本，滚动定位 + 临时高亮。
   * 支持行号优先定位（教材检索引用【📖 文件:行】）。
   */
  /**
   * 解析引用中的文件路径到 vault 相对路径。
   * 回答里 LLM 常把完整路径简写成文件名（如【📖 第1讲.md:698】），逐级兜底：
   * ① 原样（完整 vault 路径）② 教材根拼接 ③ basename 在教材目录内匹配 ④ 全局唯一匹配。
   */
  resolveRefPath(file) {
    if (!file) return null;
    const root = this.plugin.settings.textbookRoot.replace(/\\/g, "/").replace(/\/+$/, "");
    for (const p of [file, root + "/" + file]) {
      if (this.app.vault.getAbstractFileByPath(p) instanceof import_obsidian5.TFile) return p;
    }
    const name = file.split("/").pop() ?? file;
    const md2 = this.app.vault.getMarkdownFiles();
    const inRoot = md2.filter((f) => f.path.startsWith(root + "/") && f.name === name);
    if (inRoot.length === 1) return inRoot[0].path;
    const all = md2.filter((f) => f.name === name);
    if (all.length === 1) return all[0].path;
    return null;
  }
  async navigateToTextAnchor(sourcePath, quote, line) {
    let resolved = sourcePath;
    if (!(this.app.vault.getAbstractFileByPath(sourcePath) instanceof import_obsidian5.TFile)) {
      const r = this.resolveRefPath(sourcePath);
      if (!r) {
        new import_obsidian5.Notice("\u951A\u70B9\u6587\u4EF6\u4E0D\u5B58\u5728\uFF1A" + sourcePath);
        return;
      }
      resolved = r;
    }
    const f = this.app.vault.getAbstractFileByPath(resolved);
    if (!(f instanceof import_obsidian5.TFile)) {
      new import_obsidian5.Notice("\u951A\u70B9\u6587\u4EF6\u4E0D\u5B58\u5728\uFF1A" + sourcePath);
      return;
    }
    const leaf = this.app.workspace.getLeaf(false);
    await leaf.openFile(f);
    await new Promise((r) => setTimeout(r, 120));
    const editor = this.app.workspace.getActiveViewOfType(import_obsidian5.MarkdownView)?.editor;
    if (!editor) return;
    if (line && line > 0) {
      const target = Math.min(Math.max(0, line - 1), editor.lineCount() - 1);
      const from2 = { line: target, ch: 0 };
      const to3 = { line: target, ch: editor.getLine(target).length };
      editor.setSelection(from2, to3);
      editor.scrollIntoView({ from: from2, to: to3 }, true);
      editor.focus();
      window.setTimeout(() => {
        try {
          const cur = editor.getCursor();
          editor.setSelection(cur, cur);
        } catch (e) {
        }
      }, 2500);
      return;
    }
    if (!quote) return;
    const norm = (s) => String(s).replace(/\s+/g, " ").trim();
    const needle = norm(quote).slice(0, 80);
    if (!needle) return;
    const doc = editor.getValue();
    const docNorm = norm(doc);
    const idx = docNorm.indexOf(needle);
    if (idx < 0) {
      new import_obsidian5.Notice("\u672A\u80FD\u5728\u6587\u4EF6\u4E2D\u627E\u5230\u951A\u70B9\u6587\u672C");
      return;
    }
    let rawPos = 0;
    let normPos = 0;
    let found = -1;
    const chars = doc;
    while (normPos <= idx && rawPos < chars.length) {
      if (chars[rawPos] === "\n" || chars[rawPos] === " " || chars[rawPos] === "	" || chars[rawPos] === "\r") {
        rawPos++;
        continue;
      }
      if (normPos === idx) {
        found = rawPos;
        break;
      }
      normPos++;
      rawPos++;
    }
    if (found < 0) {
      found = doc.indexOf(quote.slice(0, 60));
      if (found < 0) found = doc.search(needle.slice(0, 30));
    }
    if (found < 0) {
      new import_obsidian5.Notice("\u672A\u80FD\u5728\u6587\u4EF6\u4E2D\u627E\u5230\u951A\u70B9\u6587\u672C");
      return;
    }
    const lineNo = editor.offsetToPos(found).line;
    const from = { line: lineNo, ch: 0 };
    const to2 = { line: lineNo, ch: editor.getLine(lineNo).length };
    editor.setSelection(from, to2);
    editor.scrollIntoView({ from, to: to2 }, true);
    editor.focus();
    window.setTimeout(() => {
      try {
        const cur = editor.getCursor();
        editor.setSelection(cur, cur);
      } catch (e) {
      }
    }, 2500);
  }
