      this.branchNext = false;
      this.inputEl.value = "";
      this.inputEl.placeholder = "\u8F93\u5165\u4E00\u4E2A\u65B0\u95EE\u9898\uFF0C\u6216\u4ECE\u601D\u7EF4\u5730\u56FE\u6062\u590D\u65E7\u5206\u652F\u2026";
